// Converte o evento do Agent Bot do Chatwoot em um item simples.
// Só segue adiante: evento "message_created" de mensagem RECEBIDA do cliente (incoming),
// que não seja nota privada, em conversa com status "pending" (ainda com o bot).
// Mensagens enviadas pelo próprio bot chegam como "outgoing" e são descartadas aqui (evita loop).
// Conversas "open" (já com o RH) também são descartadas: o bot não interfere.
const saida = [];

for (const item of $input.all()) {
  const b = item.json.body || item.json;

  if (b.event !== 'message_created') continue;
  if (!(b.message_type === 'incoming' || b.message_type === 0)) continue;
  if (b.private) continue;

  const conversa = b.conversation || {};
  if (conversa.status !== 'pending') continue;

  const remetente = b.sender || conversa.meta?.sender || {};
  const anexos = Array.isArray(b.attachments) ? b.attachments : [];
  const arquivo = anexos.find(a => a.file_type === 'file') || null;
  const nomeArquivo = arquivo
    ? decodeURIComponent((arquivo.data_url || '').split('?')[0].split('/').pop() || 'curriculo')
    : '';

  saida.push({
    json: {
      mensagemId: b.id,
      conversaId: conversa.id,
      contaId: b.account?.id,
      telefone: (remetente.phone_number || '').replace(/\D/g, ''),
      nome: remetente.name || '',
      texto: (b.content || '').trim(),
      tipo: arquivo ? 'document' : (anexos.length ? 'midia' : 'text'),
      documento: arquivo ? { arquivo: nomeArquivo, url: arquivo.data_url, extensao: arquivo.extension || '' } : null,
    },
  });
}

return saida;

// =====================================================================
// MOTOR DO FLUXO (versão Chatwoot): perguntas e respostas fixas, sem IA.
// Para mudar textos, vagas e horários, edite só o bloco CONFIGURAÇÃO.
// Menu em texto: o candidato responde digitando o número da opção.
// Sessão: uma por conversa do Chatwoot.
// =====================================================================

// ---------- CONFIGURAÇÃO ----------
const EMPRESA = 'Fazenda Nova Piratininga';
const TEMPO_SESSAO_MIN = 30;            // sem resposta por 30 min, a conversa recomeça
const HORARIO_RH = 'de segunda a sexta, das 8h às 17h';   // [ajustar]
const PRAZO_RETORNO = '2 dias úteis';                      // [ajustar]
const CHATWOOT_URL = 'http://rails:3000';                  // Chatwoot na rede Docker [ajustar no servidor]

// Vagas de exemplo [ajustar]
const VAGAS = [
  { titulo: 'Trabalhador rural', descricao: 'Plantio, trato e colheita' },
  { titulo: 'Tratorista', descricao: 'CNH categoria C ou superior' },
  { titulo: 'Operador de máquinas', descricao: 'Experiência mínima de 1 ano' },
  { titulo: 'Auxiliar administrativo', descricao: 'Ensino médio completo' },
];
const TURNOS = ['Manhã', 'Tarde', 'Noite', 'Qualquer turno'];

const MSG_FINAL = `Obrigado pelo contato com o Recrutamento e Seleção da ${EMPRESA}! 😊\nQuando quiser falar de novo, é só mandar uma mensagem.`;

const MSG_HANDOFF =
  `Certo! Sua conversa foi encaminhada para a equipe de RH, que atende ${HORARIO_RH}.\n\n` +
  'Pode escrever sua mensagem aqui. Uma pessoa do RH vai responder por esta conversa.';

// ---------- TELAS DO FLUXO (texto simples) ----------
const numerada = (itens) => itens.map((t, i) => `${i + 1}. ${t}`).join('\n');

const menu = (intro) =>
  `${intro ? intro + '\n\n' : ''}Como podemos ajudar? Digite o número da opção:\n` +
  numerada(['Ver vagas abertas', 'Cadastrar currículo', 'Acompanhar processo', 'Falar com o RH']);

const telaVagas = () =>
  `Vagas abertas no momento:\n\n${VAGAS.map(v => `• *${v.titulo}*: ${v.descricao}`).join('\n')}\n\n` +
  'Digite:\n1. Quero me candidatar\n2. Voltar ao menu';

const perguntaVaga = () =>
  '3/6. Para qual vaga você quer se candidatar? Digite o número:\n' +
  numerada([...VAGAS.map(v => v.titulo), 'Banco de talentos (nenhuma das vagas)']);

const perguntaExperiencia = () => '4/6. Você já trabalhou nessa função? Digite:\n1. Sim\n2. Não';
const perguntaTurno = () => `5/6. Qual turno você pode trabalhar? Digite o número:\n${numerada(TURNOS)}`;
const perguntaCurriculo = () => '6/6. Envie seu currículo em PDF ou Word por aqui.\nSe não tiver agora, digite *pular*.';

const fichaCadastro = (d) =>
  `*Nome:* ${d.nome}\n*Cidade:* ${d.cidade}\n*Vaga:* ${d.vaga}\n*Experiência na função:* ${d.experiencia}\n` +
  `*Turno:* ${d.turno}\n*Currículo:* ${d.curriculo ? d.curriculo.arquivo : 'não enviado'}`;

const resumo = (d) => `Confira seus dados:\n\n${fichaCadastro(d)}\n\nEstá tudo certo? Digite:\n1. Confirmar\n2. Corrigir dados`;

// ---------- AUXILIARES ----------
const norm = (s) => (s || '').toString().trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '');
const SO_TEXTO = 'Por enquanto só consigo ler mensagens de texto. Por favor, digite sua resposta.';
const numero = (e, max) => (/^\d+$/.test(e) && +e >= 1 && +e <= max ? +e : 0);

// =====================================================================
const db = $getWorkflowStaticData('global');   // memória do fluxo (só grava com o workflow PUBLICADO)
db.sessoes = db.sessoes || {};
db.registros = db.registros || [];
const agora = Date.now();
const saida = [];

// Apaga sessões paradas há mais de 7 dias, para a memória não crescer sem limite
for (const [k, v] of Object.entries(db.sessoes)) {
  if (agora - (v.atualizadoEm || 0) > 7 * 24 * 3600 * 1000) delete db.sessoes[k];
}

for (const item of $input.all()) {
  const m = item.json;
  const chave = String(m.conversaId);
  const r = [];        // mensagens ao candidato, em ordem
  const notas = [];    // notas privadas para o RH (aparecem só dentro do Chatwoot)
  let handoff = false; // true = passar a conversa para o RH (status "open")
  let s = db.sessoes[chave];

  // Ignora evento repetido
  if (s && s.ultimaMsgId === m.mensagemId) continue;

  const e = norm(m.texto);
  const ehTexto = m.tipo === 'text' && e !== '';
  const primeiroNome = (m.nome || '').split(' ')[0];

  const novaSessao = () => ({ etapa: 'menu', dados: {}, inicio: agora });
  const iniciarCadastro = () => {
    s.dados = {};
    r.push('Vamos fazer seu cadastro. São 6 perguntas rápidas.\nA qualquer momento, digite *menu* para voltar ao início ou *sair* para encerrar.');
    r.push('1/6. Qual é o seu nome completo?');
    s.etapa = 'cad_nome';
  };

  // Sessão nova se: não existe, ficou parada, terminou, ou já tinha ido para o RH
  const expirou = !s || (agora - s.atualizadoEm) > TEMPO_SESSAO_MIN * 60000 || ['fim', 'humano'].includes(s.etapa);

  if (expirou) {
    s = novaSessao();
    const saudacao = primeiroNome ? `Olá, ${primeiroNome}! 👋` : 'Olá! 👋';
    r.push(menu(`${saudacao}\nVocê está no atendimento de Recrutamento e Seleção da ${EMPRESA}.`));
  } else if (['menu', 'inicio', 'voltar', 'reiniciar'].includes(e)) {
    s = novaSessao();
    r.push(menu('Voltamos ao início.'));
  } else if (e === 'sair') {
    s.etapa = 'fim';
    r.push(`Atendimento encerrado.\n\n${MSG_FINAL}`);
  } else {
    const d = s.dados;
    switch (s.etapa) {

      case 'menu': {
        if (e === '1') {
          r.push(telaVagas());
          s.etapa = 'vagas';
        } else if (e === '2') {
          iniciarCadastro();
        } else if (e === '3') {
          r.push('Para consultar seu processo, digite em uma mensagem seu *nome completo* e a *vaga* para a qual você se candidatou.');
          s.etapa = 'acomp_info';
        } else if (e === '4' || ['rh', 'atendente', 'humano'].includes(e)) {
          r.push(MSG_HANDOFF);
          s.etapa = 'humano';
          handoff = true;
        } else {
          r.push(menu('Não entendi sua resposta.'));
        }
        break;
      }

      case 'vagas': {
        if (e === '1' || e.includes('candidat')) iniciarCadastro();
        else if (e === '2') { s = novaSessao(); r.push(menu()); }
        else r.push(telaVagas());
        break;
      }

      case 'cad_nome': {
        const nome = (m.texto || '').trim().replace(/\s+/g, ' ');
        if (!ehTexto) r.push(SO_TEXTO);
        else if (nome.split(' ').length < 2 || nome.length < 5) r.push('Por favor, digite seu *nome e sobrenome*.');
        else {
          d.nome = nome;
          r.push('2/6. Em qual cidade você mora?');
          s.etapa = 'cad_cidade';
        }
        break;
      }

      case 'cad_cidade': {
        const cidade = (m.texto || '').trim();
        if (!ehTexto) r.push(SO_TEXTO);
        else if (cidade.length < 2) r.push('Por favor, digite o nome da sua cidade.');
        else {
          d.cidade = cidade;
          r.push(perguntaVaga());
          s.etapa = 'cad_vaga';
        }
        break;
      }

      case 'cad_vaga': {
        const n = numero(e, VAGAS.length + 1);
        if (n) {
          d.vaga = n <= VAGAS.length ? VAGAS[n - 1].titulo : 'Banco de talentos';
          r.push(perguntaExperiencia());
          s.etapa = 'cad_experiencia';
        } else {
          r.push(perguntaVaga());
        }
        break;
      }

      case 'cad_experiencia': {
        if (['1', 'sim', 's'].includes(e)) d.experiencia = 'Sim';
        else if (['2', 'nao', 'n'].includes(e)) d.experiencia = 'Não';
        if (d.experiencia) {
          r.push(perguntaTurno());
          s.etapa = 'cad_turno';
        } else {
          r.push(perguntaExperiencia());
        }
        break;
      }

      case 'cad_turno': {
        const n = numero(e, TURNOS.length) || (TURNOS.findIndex(t => norm(t) === e) + 1);
        if (n) {
          d.turno = TURNOS[n - 1];
          r.push(perguntaCurriculo());
          s.etapa = 'cad_curriculo';
        } else {
          r.push(perguntaTurno());
        }
        break;
      }

      case 'cad_curriculo': {
        if (m.tipo === 'document' && m.documento) {
          d.curriculo = m.documento;
        } else if (e === 'pular') {
          d.curriculo = null;
        } else {
          r.push('Não recebi um arquivo. Envie o currículo em PDF ou Word, ou digite *pular*.');
          break;
        }
        r.push(resumo(d));
        s.etapa = 'cad_confirmar';
        break;
      }

      case 'cad_confirmar': {
        if (e === '1' || e === 'confirmar') {
          db.registros.push({ conversa: chave, telefone: m.telefone, ...d, concluidoEm: new Date(agora).toISOString() });
          if (db.registros.length > 500) db.registros.shift();
          notas.push(`📋 Cadastro recebido pelo bot\n\n${fichaCadastro(d)}${d.curriculo ? `\nArquivo: ${d.curriculo.url}` : ''}`);
          r.push(`Cadastro enviado, ${d.nome.split(' ')[0]}! ✅\nSe o seu perfil combinar com a vaga, o RH vai entrar em contato por este WhatsApp.\n\n${MSG_FINAL}`);
          s.etapa = 'fim';
        } else if (e === '2' || e === 'corrigir') {
          s.dados = {};
          r.push('Sem problemas, vamos refazer o cadastro.');
          r.push('1/6. Qual é o seu nome completo?');
          s.etapa = 'cad_nome';
        } else {
          r.push(resumo(d));
        }
        break;
      }

      case 'acomp_info': {
        if (!ehTexto) { r.push(SO_TEXTO); break; }
        db.registros.push({ conversa: chave, telefone: m.telefone, tipo: 'acompanhamento', mensagem: m.texto, concluidoEm: new Date(agora).toISOString() });
        if (db.registros.length > 500) db.registros.shift();
        notas.push(`🔎 Pedido de acompanhamento de processo\n\n${m.texto}`);
        r.push(`Recebemos sua mensagem e encaminhamos sua conversa para a equipe de RH, que atende ${HORARIO_RH}.\nA resposta vem por aqui em até ${PRAZO_RETORNO}.`);
        s.etapa = 'humano';   // passa para o RH, como na opção 4
        handoff = true;
        break;
      }

      default: {
        s = novaSessao();
        r.push(menu());
      }
    }
  }

  s.ultimaMsgId = m.mensagemId;
  s.atualizadoEm = agora;
  db.sessoes[chave] = s;

  const base = { chatwootUrl: CHATWOOT_URL, contaId: m.contaId, conversaId: m.conversaId, etapa: s.etapa, handoff };
  for (const content of r) saida.push({ json: { ...base, content, privado: false } });
  for (const content of notas) saida.push({ json: { ...base, content, privado: true } });
}

return saida;

// Roda DEPOIS de enviar as mensagens: separa as conversas que pediram o RH (opção 4),
// para que o aviso chegue ao candidato antes de a conversa mudar para "open".
const vistos = new Set();
const saida = [];

for (const it of $('Motor do fluxo').all()) {
  const j = it.json;
  if (!j.handoff || vistos.has(j.conversaId)) continue;
  vistos.add(j.conversaId);
  saida.push({ json: { chatwootUrl: j.chatwootUrl, contaId: j.contaId, conversaId: j.conversaId } });
}

return saida;
